/**
 * Extracts primary location text while excluding detour/alternate route text
 * to prevent false positives when e.g. a Johannesburg post recommends "Use R21" or "Pretoria Rd"
 */
function getPrimaryLocationText(item: Partial<FeedItem>): string {
  const parts: string[] = [
    item.roadwayName || '',
    item.location || '',
    item.direction || '',
    item.eventSubType || ''
  ];

  if (item.content) {
    // Strip detour/alternative route suggestions from keyword matching
    let primaryContent = item.content;
    const detourSplit = primaryContent.split(/(?:Use |Divert via |Alternative route|Detour:)/i);
    parts.push(detourSplit[0] || '');
  }

  return parts.filter(Boolean).join(' ').toLowerCase();
}

export function isPretoriaItem(item: Partial<FeedItem>): boolean {
  if (!item) return false;

  // 1. Explicit City Tag / Handle / Author
  const cityProp = ((item as any).city || '').toLowerCase();
  if (cityProp === 'pretoria' || cityProp === 'tshwane' || cityProp === 'centurion') return true;
  if (cityProp === 'johannesburg' || cityProp === 'joburg' || cityProp === 'sandton' || cityProp === 'durban' || cityProp === 'cape town' || cityProp === 'gqeberha') return false;

  const handle = (item.handle || '').toLowerCase();
  if (handle.includes('trafficpta') || handle.includes('traffic_pta') || handle.includes('pretoria')) return true;
  if (handle.includes('trafficjhb') || handle.includes('traffic_jhb') || handle.includes('joburg') || handle.includes('traffickzn') || handle.includes('trafficwc') || handle.includes('trafficec')) return false;

  const author = (item.author || '').toLowerCase();
  if (author.includes('(pretoria)') || author.includes('tshwane') || author.includes('centurion')) return true;
  if (author.includes('(johannesburg)') || author.includes('(joburg)') || author.includes('(sandton)') || author.includes('(durban)') || author.includes('(cape town)') || author.includes('(gqeberha)')) return false;

  // 2. Explicit Location Prefix Check
  const location = (item.location || '').toLowerCase();
  if (location.startsWith('pretoria') || location.includes('pretoria •') || location.startsWith('centurion') || location.includes('centurion •') || location.startsWith('tshwane')) {
    return true;
  }
  if (location.startsWith('johannesburg') || location.includes('johannesburg •') || location.startsWith('sandton') || location.startsWith('bedfordview') || location.startsWith('edenvale') || location.startsWith('germiston') || location.startsWith('boksburg') || location.startsWith('alberton') || location.startsWith('roodepoort') || location.startsWith('randburg') || location.startsWith('soweto') || location.startsWith('midrand') || location.startsWith('durban') || location.startsWith('cape town') || location.startsWith('gqeberha')) {
    return false;
  }

  // 3. Lat/Lng bounds check (Pretoria & Centurion Metro Box)
  if (typeof item.latitude === 'number' && typeof item.longitude === 'number' && !isNaN(item.latitude) && !isNaN(item.longitude)) {
    const lat = item.latitude;
    const lng = item.longitude;
    // Pretoria & Centurion: lat >= -25.96 down to -25.40, lng 27.80 to 28.55
    if (lat >= -25.96 && lat <= -25.40 && lng >= 27.80 && lng <= 28.55) {
      return true;
    }
    // If it's south of -25.96 and in Gauteng lng, it's Johannesburg / East / West Rand
    if (lat < -25.96 && lat >= -26.60 && lng >= 27.50 && lng <= 28.60) {
      return false;
    }
  }

  // 4. Primary text keyword matching (excluding detour suggestions)
  const primaryText = getPrimaryLocationText(item);

  // If primary text specifically matches a strong Johannesburg landmark or other province, do NOT classify as Pretoria
  const matchesJhbStrong = JOHANNESBURG_EXPLICIT_LOCATIONS.some(kw => primaryText.includes(kw));
  if (matchesJhbStrong) {
    return false;
  }

  return PRETORIA_EXPLICIT_LOCATIONS.some(kw => primaryText.includes(kw));
}

export function isJohannesburgItem(item: Partial<FeedItem>): boolean {
  if (!item) return false;

  // 1. Explicit City Tag / Handle / Author
  const cityProp = ((item as any).city || '').toLowerCase();
  if (cityProp === 'johannesburg' || cityProp === 'joburg' || cityProp === 'sandton' || cityProp === 'alberton') return true;
  if (cityProp === 'pretoria' || cityProp === 'tshwane' || cityProp === 'centurion' || cityProp === 'durban' || cityProp === 'cape town' || cityProp === 'gqeberha') return false;

  const handle = (item.handle || '').toLowerCase();
  if (handle.includes('trafficjhb') || handle.includes('traffic_jhb') || handle.includes('joburg')) return true;
  if (handle.includes('trafficpta') || handle.includes('traffic_pta') || handle.includes('pretoria') || handle.includes('traffickzn') || handle.includes('trafficwc') || handle.includes('trafficec')) return false;

  const author = (item.author || '').toLowerCase();
  if (author.includes('(johannesburg)') || author.includes('(joburg)') || author.includes('(sandton)') || author.includes('(alberton)')) return true;
  if (author.includes('(pretoria)') || author.includes('tshwane') || author.includes('centurion') || author.includes('(durban)') || author.includes('(cape town)') || author.includes('(gqeberha)')) return false;

  // 2. Explicit Location Prefix Check
  const location = (item.location || '').toLowerCase();
  if (location.startsWith('johannesburg') || location.includes('johannesburg •') || location.startsWith('sandton') || location.startsWith('bedfordview') || location.startsWith('edenvale') || location.startsWith('germiston') || location.startsWith('boksburg') || location.startsWith('alberton') || location.startsWith('roodepoort') || location.startsWith('randburg') || location.startsWith('soweto') || location.startsWith('midrand')) {
    return true;
  }
  if (location.startsWith('pretoria') || location.includes('pretoria •') || location.startsWith('centurion') || location.includes('centurion •') || location.startsWith('tshwane')) {
    return false;
  }

  // 3. Lat/Lng bounds check (Johannesburg, Sandton, East & West Rand Box)
  if (typeof item.latitude === 'number' && typeof item.longitude === 'number' && !isNaN(item.latitude) && !isNaN(item.longitude)) {
    const lat = item.latitude;
    const lng = item.longitude;
    // Johannesburg / Rand: lat < -25.96 down to -26.60, lng 27.50 to 28.60
    if (lat < -25.96 && lat >= -26.60 && lng >= 27.50 && lng <= 28.60) {
      return true;
    }
    // If it's north of -25.96 and in Tshwane/Centurion box, it's Pretoria
    if (lat >= -25.96 && lat <= -25.40 && lng >= 27.80 && lng <= 28.55) {
      return false;
    }
  }

  // 4. Primary text keyword matching (excluding detour suggestions)
  const primaryText = getPrimaryLocationText(item);

  // If primary text matches Pretoria landmarks, do not classify as Joburg
  const matchesPtaStrong = PRETORIA_EXPLICIT_LOCATIONS.some(kw => primaryText.includes(kw));
  if (matchesPtaStrong) {
    return false;
  }

  return JOHANNESBURG_EXPLICIT_LOCATIONS.some(kw => primaryText.includes(kw));
}

/**
 * Check if a FeedItem belongs to KwaZulu-Natal (Durban, PMB, North & South Coast, N2, N3)
 */
export function isKZNItem(item: Partial<FeedItem>): boolean {
  if (!item) return false;
  const reg = resolveItemRegion(item);
  if (reg === 'KwaZulu-Natal') return true;

  const handle = (item.handle || '').toLowerCase();
  if (handle.includes('traffickzn') || handle.includes('n3tc')) return true;

  const primaryText = getPrimaryLocationText(item);
  return KZN_EXPLICIT_LOCATIONS.some(kw => primaryText.includes(kw));
}

