/**
 * Check if a FeedItem belongs to Gauteng (Pretoria, Johannesburg, East/West/South Rand)
 */
export function isGautengItem(item: Partial<FeedItem>): boolean {
  if (!item) return false;
  const reg = resolveItemRegion(item);
  if (reg === 'Gauteng') return true;
  return isPretoriaItem(item) || isJohannesburgItem(item);
}

/**
 * Check if a FeedItem belongs to any specific province
 */
export function isProvinceItem(item: Partial<FeedItem>, targetProvince: SARegionId): boolean {
  if (!item) return false;
  if (targetProvince === 'all') return true;
  const resolved = resolveItemRegion(item);
  if (resolved === targetProvince) return true;

  switch (targetProvince) {
    case 'Gauteng':
      return isGautengItem(item);
    case 'KwaZulu-Natal':
      return isKZNItem(item);
    case 'Western Cape':
      return isWesternCapeItem(item);
    case 'Eastern Cape':
      return isEasternCapeItem(item);
    case 'Free State':
      return isFreeStateItem(item);
    case 'Mpumalanga':
      return isMpumalangaItem(item);
    case 'Limpopo':
      return isLimpopoItem(item);
    case 'North West':
      return isNorthWestItem(item);
    case 'Northern Cape':
      return isNorthernCapeItem(item);
    default:
      return false;
  }
}

export interface ComprehensiveTrafficCounts {
  all: number;
  pretoria: number;
  johannesburg: number;
  gauteng: number;
  kzn: number;
  westernCape: number;
  easternCape: number;
  freeState: number;
  mpumalanga: number;
  limpopo: number;
  northWest: number;
  northernCape: number;
  googleMapsScansCount: number;
  pretoriaDelays: number;
  johannesburgDelays: number;
  gautengDelays: number;
  kznDelays: number;
  wcDelays: number;
  ecDelays: number;
  fsDelays: number;
  mpDelays: number;
  lpDelays: number;
  nwDelays: number;
  ncDelays: number;
}

export function getComprehensiveTrafficCounts(items: FeedItem[]): ComprehensiveTrafficCounts {
  let pretoria = 0;
  let johannesburg = 0;
  let gauteng = 0;
  let kzn = 0;
  let westernCape = 0;
  let easternCape = 0;
  let freeState = 0;
  let mpumalanga = 0;
  let limpopo = 0;
  let northWest = 0;
  let northernCape = 0;
  let googleMapsScansCount = 0;

  let pretoriaDelays = 0;
  let johannesburgDelays = 0;
  let gautengDelays = 0;
  let kznDelays = 0;
  let wcDelays = 0;
  let ecDelays = 0;
  let fsDelays = 0;
  let mpDelays = 0;
  let lpDelays = 0;
  let nwDelays = 0;
  let ncDelays = 0;

  for (const item of items) {
    if (isGoogleMapsScanItem(item)) {
      googleMapsScansCount++;
    }

    const reg = resolveItemRegion(item);
    const isPta = isPretoriaItem(item);
    const isJhb = isJohannesburgItem(item);
    const isGp = reg === 'Gauteng' || isPta || isJhb;
    const isK = reg === 'KwaZulu-Natal' || isKZNItem(item);
    const isW = reg === 'Western Cape' || isWesternCapeItem(item);
    const isE = reg === 'Eastern Cape' || isEasternCapeItem(item);
    const isF = reg === 'Free State' || isFreeStateItem(item);
    const isM = reg === 'Mpumalanga' || isMpumalangaItem(item);
    const isL = reg === 'Limpopo' || isLimpopoItem(item);
    const isN = reg === 'North West' || isNorthWestItem(item);
    const isNc = reg === 'Northern Cape' || isNorthernCapeItem(item);

    const hasDelay = 
      item.category === 'traffic' ||
      item.category === 'congestion' ||
      item.category === 'crash' ||
      item.category === 'spiking' ||
      item.content.toLowerCase().includes('delay') ||
      item.content.toLowerCase().includes('heavy') ||
      item.content.toLowerCase().includes('bottleneck');

    if (isGp) {
      gauteng++;
      if (hasDelay) gautengDelays++;
      if (isPta) {
        pretoria++;
        if (hasDelay) pretoriaDelays++;
      }
      if (isJhb) {
        johannesburg++;
        if (hasDelay) johannesburgDelays++;
      }
    } else if (isK) {
      kzn++;
      if (hasDelay) kznDelays++;
    } else if (isW) {
      westernCape++;
      if (hasDelay) wcDelays++;
    } else if (isE) {
      easternCape++;
      if (hasDelay) ecDelays++;
    } else if (isF) {
      freeState++;
      if (hasDelay) fsDelays++;
    } else if (isM) {
      mpumalanga++;
      if (hasDelay) mpDelays++;
    } else if (isL) {
      limpopo++;
      if (hasDelay) lpDelays++;
    } else if (isN) {
      northWest++;
      if (hasDelay) nwDelays++;
    } else if (isNc) {
      northernCape++;
      if (hasDelay) ncDelays++;
    }
  }

  return {
    all: items.length,
    pretoria,
    johannesburg,
    gauteng,
    kzn,
    westernCape,
    easternCape,
    freeState,
    mpumalanga,
    limpopo,
    northWest,
    northernCape,
    googleMapsScansCount,
    pretoriaDelays,
    johannesburgDelays,
    gautengDelays,
    kznDelays,
    wcDelays,
    ecDelays,
    fsDelays,
    mpDelays,
    lpDelays,
    nwDelays,
    ncDelays
  };
}

// Backward compatibility alias
export const getCityTrafficCounts = (items: FeedItem[]) => {
  const comp = getComprehensiveTrafficCounts(items);
  return {
    pretoria: comp.pretoria,
    johannesburg: comp.johannesburg,
    allGauteng: comp.gauteng,
    pretoriaDelays: comp.pretoriaDelays,
    johannesburgDelays: comp.johannesburgDelays
  };
};

